(function initContactForm(){'use strict';var FORMSPREE_ACTION='https://formspree.io/f/xbdawwpg';var COOLDOWN_MS=30000;var lastSubmitTime=0;var form=document.getElementById('contact-form');if(!form)return;var submitBtn=form.querySelector('[type="submit"]');var successMsg=document.getElementById('form-success');var errorMsg=document.getElementById('form-error');function validateField(input){var errorEl=document.getElementById(input.id+'-error');if(!errorEl)return true;var valid=true;var message='';if(input.required&&!input.value.trim()){valid=false;message='This field is required.';}else if(input.type==='email'&&input.value.trim()&&!input.validity.valid){valid=false;message='Please enter a valid email address.';}else if(input.tagName==='TEXTAREA'&&input.minLength>0&&input.value.trim().length<input.minLength){valid=false;message='Please enter at least '+input.minLength+' characters.';}else if(input.type==='checkbox'&&input.required&&!input.checked){valid=false;message='Please confirm your consent to continue.';}
errorEl.textContent=message;input.setAttribute('aria-invalid',valid?'false':'true');return valid;}
function validateAll(){var fields=form.querySelectorAll('[required]');var allValid=true;fields.forEach(function(field){if(!validateField(field))allValid=false;});return allValid;}
form.querySelectorAll('input, textarea, select').forEach(function(field){field.addEventListener('blur',function(){if(field.value!==''||field===document.activeElement){validateField(field);}});field.addEventListener('input',function(){var errorEl=document.getElementById(field.id+'-error');if(errorEl&&field.getAttribute('aria-invalid')==='true'){validateField(field);}});});form.addEventListener('submit',function(e){e.preventDefault();var now=Date.now();if(now-lastSubmitTime<COOLDOWN_MS){var remaining=Math.ceil((COOLDOWN_MS-(now-lastSubmitTime))/1000);if(errorMsg){errorMsg.querySelector('p').textContent='Please wait '+remaining+' seconds before sending another message.';errorMsg.hidden=false;}
return;}
if(!validateAll()){var firstInvalid=form.querySelector('[aria-invalid="true"]');if(firstInvalid)firstInvalid.focus();return;}
submitBtn.disabled=true;submitBtn.textContent='Sending\u2026';if(successMsg)successMsg.hidden=true;if(errorMsg)errorMsg.hidden=true;var data=new FormData(form);fetch(FORMSPREE_ACTION,{method:'POST',body:data,headers:{'Accept':'application/json'}}).then(function(response){if(response.ok){lastSubmitTime=Date.now();form.querySelectorAll('.form-group').forEach(function(g){g.style.display='none';});submitBtn.style.display='none';if(successMsg)successMsg.hidden=false;form.reset();}else{return response.json().then(function(json){throw new Error(json.error||'Submission failed.');});}}).catch(function(){if(errorMsg){var p=errorMsg.querySelector('p');if(p)p.innerHTML='Something went wrong. Please try again or call us at <a href="tel:+15123352250">512-335-2250</a>.';errorMsg.hidden=false;}}).finally(function(){submitBtn.disabled=false;submitBtn.textContent='Send Message';});});})();